#include "NamIrBrowser.h"
#include "ui/PmxTheme.h"
namespace pmx::ui
{
NamIrBrowser::NamIrBrowser(){title.setText("Find your amp. Choose your cabinet.",juce::dontSendNotification);title.setFont(juce::FontOptions(24.0f,juce::Font::bold));title.setColour(juce::Label::textColourId,juce::Colour(Theme::text));subtitle.setText("Imported sounds stay in your PMX library.",juce::dontSendNotification);subtitle.setColour(juce::Label::textColourId,juce::Colour(Theme::mutedText));ampLabel.setText("AMP MODEL",juce::dontSendNotification);cabLabel.setText("CABINET IR",juce::dontSendNotification);for(auto*l:{&ampLabel,&cabLabel})l->setColour(juce::Label::textColourId,juce::Colour(Theme::mutedText));for(auto*c:{static_cast<juce::Component*>(&title),&subtitle,&ampLabel,&cabLabel,&importNam,&importIr,&load})addAndMakeVisible(*c);for(auto&b:amps)addAndMakeVisible(b);for(auto&b:cabs)addAndMakeVisible(b);importNam.onClick=[this]{if(onImportNam)onImportNam();};importIr.onClick=[this]{if(onImportIr)onImportIr();};load.onClick=[this]{if(onLoadSelected)onLoadSelected();};}
void NamIrBrowser::paint(juce::Graphics&g){g.setColour(juce::Colour(Theme::panel));g.fillRoundedRectangle(getLocalBounds().toFloat(),12);g.setColour(juce::Colour(Theme::border));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(.5f),12,1);}
void NamIrBrowser::resized(){auto r=getLocalBounds().reduced(26);title.setBounds(r.removeFromTop(34));subtitle.setBounds(r.removeFromTop(26));r.removeFromTop(12);auto cols=r.removeFromTop(300);auto left=cols.removeFromLeft(cols.getWidth()/2).reduced(0,0,10,0);auto right=cols.reduced(10,0,0,0);ampLabel.setBounds(left.removeFromTop(24));cabLabel.setBounds(right.removeFromTop(24));for(auto&b:amps)b.setBounds(left.removeFromTop(54).reduced(0,5));for(auto&b:cabs)b.setBounds(right.removeFromTop(54).reduced(0,5));auto bottom=r.removeFromBottom(40);importNam.setBounds(bottom.removeFromLeft(130));importIr.setBounds(bottom.removeFromLeft(130).reduced(8,0));load.setBounds(bottom.removeFromRight(170));}
}
